// === Tab: mySketch ===
// PBa
// 2020-05-13
// Percolation : simulation of fire extension
//*******************************************************************************

let black=color(0,0,0);
let cl=color(0,255,0);
let red=color(255,0,0);
let green=color(0,255,0);
let blue=color(0,0,255);
let lblue=color(191,217,252);
let backg=color(255,255,255);
let yellow=color(224,245,7);
let orange=color(234,77,33);
let white=color(255,255,255);
let violet=color(219,7,198);

let init,fc;
let nlig=50;
let ncol=50;
let nb;
let pr,pr1,newpr1;
let espl,espc;
let col;
let tab[][]=new Array(nlig)[ncol];
let perco[][] =new Array(nlig)[ncol];
ArrayList<Elp> Tabp;
let percent;

//*************************************************
function setup()
{  
  createCanvas(800, 760);
  frameRate(10000);
  Tabp = new ArrayList<Elp>();  
  pr=0.7;
  pr1=0.52;
  nb=nlig*ncol;  
  espl=(width-2*100)/nlig;
  espc=(height-2*50)/ncol;  
  rectMode(CORNER);
  ellipseMode(CENTER); 
  background(170,170,170);
  init=0;
  newpr1=pr1;
  //noLoop();
}

//******************************************************
function draw()
{
  if (init==0)
    {
      pr1=newpr1;
      fill(lblue);      
      rect(630,660,150,30,4);
      fill(green);
      rect(630,660,150*pr1,30,4);
      textSize(18);
      fill(black);
      text(nf(pr1,0,2),675,680);
      fill(red);
      rect(680,710,50,30);
      fill(black);      
      text("GO",690,730);
      textSize(28);
      text("FIRE PROPAGATION IN ARRAY OF TREES FROM CENTER",40,30);
      for(i=0;i<nlig;i++)       
        { 
          for(j=0;j<ncol;j++)
            {   
             tab[i][j]=0;      // SAFE        
            }      
        }
      tab[24][25]=1;           //let FIRE
      tab[24][26]=1;
      tab[25][25]=1;
      tab[25][26]=1;
      aff(tab);
      initlook();
      if(Tabp.size()>0)
        {
          //println("Tabp.size=",Tabp.size());
          fill(black);
          textSize(18);
          perco=tab;
          text("Click to change fire extension probability from one tree to another",10,680);
          init=2;
        }
      else
        {
          text("NO INITIAL TREE IN FIRE",50,700);
          init=1;
        }      
    }
  if(init==1)
    {
      fill(black);  
    }
  if(init==2)
    {
      tabperco();
      aff(perco);
      if(Tabp.size()==0)
        {
          init=4;
          //println("FINISHED");
          textSize(20);
          fill(black);
          percent=0;
          for(i=0;i<nlig;i++)
            {
              for(j=0;j<ncol;j++)
                {
                  if(tab[i][j]==2)
                  percent++;
                }
            }           
           percent=(percent/nb)*100;
           if(endlook()==true)
             text(" FIRE SPREAD TO FRONTIER.   % BURNT TREES = "+nf(percent,0,2)+"%",120,730);
           else
            text(" FIRE LIMITED.   % BURNT TREES = "+nf(percent,0,2)+"%",120,730);         
        }
      else
        {
          //println("Init=2,Tabp.size=",Tabp.size());         
        }
    }
}
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function initlook()
{
  for(i=0;i<nlig;i++)
    {
      for(j=0;j<ncol;j++)
        {
          if(tab[i][j]==1)
            {
              Tabp.add(new Elp(i,j));             
            }
        }
    }    
}
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function endlook()
{
  let endc=0;
  for(j=0;j<ncol;j++)
    {
      if(perco[0][j]==2 || perco[nlig-1][j]==2)
        {
          endc++;
        }
    }
  for(i=0;i<nlig;i++)
    {
      if(perco[i][0]==2 || perco[i][ncol-1]==2)
        {
          endc++;
        }
    }  
  if(endc>0)
    return true;
  else
    return false;
}
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%      
function tabperco()
{
   let len=Tabp.size();
   let el=Tabp.get(len-1);
   //println("TABPERCO framecount=",frameCount,len,el.x,el.y);
   perco[el.x][el.y]=2;
   let det=0;
   if(el.y>0)
    {
      if(tab[el.x][el.y-1]==0)                    // let sain ??
        {
         let prob=random(0,1);
         if(prob<pr1)
           {
             perco[el.x][el.y-1]=2;
             Tabp.add(new Elp(el.x,el.y-1));         
            det++;
           }
        }
    }
   if(el.y<ncol-1)
     {   
      if(tab[el.x][el.y+1]==0)                    // Droite
        {
          var prob=random(0,1);
          if(prob<pr1)
           {
             perco[el.x][el.y+1]=2;
            Tabp.add(new Elp(el.x,el.y+1));         
            det++;
           }         
        }
     }
    if(el.x>0)                                   //Dessus
      {
        if(tab[el.x-1][el.y]==0)
          {
            var prob=random(0,1);
            if(prob<pr1)
              {
                perco[el.x-1][el.y]=2;
                Tabp.add(new Elp(el.x-1,el.y));         
                det++;
              }
          }
      }
   if(el.x<nlig-1)                                //Dessous
     {   
      if(tab[el.x+1][el.y]==0)
        {
          var prob=random(0,1);
          if(prob<pr1)
            {
          perco[el.x+1][el.y]=2;
          Tabp.add(new Elp(el.x+1,el.y));         
          det++;
            }
        }
     }
   if(det>0)
      {
        Tabp.remove(el);
        //println("REMOVE");
        init=2;
      }
    else
      {
        Tabp.remove(el);
      }
 // return perco;
}
//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
function aff(tab[][])
{
  for(i=0;i<nlig;i++)       
    {   
      for(j=0;j<ncol;j++)
        {
          let cx=80+j*espc;
          let cy=50+i*espl;
          if(tab[i][j]==1) 
            {
              col=yellow;          // let FIRE
              fill(col);
            }
          else
            {
              noFill();
              col=green;         // SAFE
            }
         if(tab[i][j]==2) 
            {
              col=orange;        // PERCO
              fill(col);
            }         

          strokeWeight(2);
          stroke(col);
          //fill(col);
          ellipse(cx,cy,8,8);
        }
     }  
}      

//%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
class Elp
{
  x;
  y;
  Col;

  constructor(x_, y_)
    {
      x=x_;
